sop:
@c1 syntax.clause form=imperative verb="darw" complement=$n1
@n1 syntax.nominal dependent="a" dependent="big" head="sun"
@c2 syntax.clause form=nonfinite verb="overlapping" complement=$n2
@n2 syntax.nominal dependent="the" head="cloud"
@r1 syntax.relation from=$n1 to=$c2

@c1 syntax.clause form=imperative verb="tunr" complement=$n1
@n1 syntax.nominal dependent="the" head="duck"
