@n2 syntax.nominal dependent="the" head="pond"
@r2 syntax.relation marker="behind" from=$n2 to=$n3
@n3 syntax.nominal dependent="the" head="tent"
@r3 syntax.relation marker="to" from=$c1 to=$c2
@c2 syntax.clause form=nonfinite verb="face" modifier="left"

@c1 syntax.clause form=imperative verb="ad" complement=$n1
@n1 syntax.nominal dependent="a" head="plane"
